checks.command:
node --input-type=module <<'NODE'
import { readFileSync } from "node:fs";
import { artifactDigest, taskContractDigest, sha256 } from "./scripts/remediation/board.mjs";
const artifact = JSON.parse(readFileSync("docs/remediation/evidence/W06.06/artifact.json","utf8"));
const contract = JSON.parse(readFileSync("docs/remediation/design/W06.06/task-contract-v1.json","utf8"));
const worker = JSON.parse(readFileSync("docs/remediation/evidence/W06.06/worker.json","utf8"));
const checks = artifact.files.map(p => ({ path:p.path, sha256:sha256(readFileSync(p.path)), expected:p.sha256 }));
const diffChecks = worker.scoped_diff.files.map(d => {
  const lines=readFileSync(d.path,"utf8").split("\n"), patch=d.output.split("\n"), restored=[]; let cursor=0;
  for(let i=2;i<patch.length;i++){
    const head=/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(patch[i]);
    if(!head) continue;
    const start=Number(head[3])-1;
    restored.push(...lines.slice(cursor,start)); cursor=start;
    for(i++;i<patch.length&&!patch[i].startsWith("@@ ");i++){
      const p=patch[i];
      if(!p) continue;
      if(p[0]===" "||p[0]==="+"){
        if(lines[cursor]!==p.slice(1)) throw new Error("diff/current mismatch: "+d.path);
        cursor++;
      }
      if(p[0]===" "||p[0]==="-") restored.push(p.slice(1));
    }
    i--;
  }
  restored.push(...lines.slice(cursor));
  return {path:d.path, reconstructed_admission_sha256:sha256(restored.join("\n")), expected:d.stdin_sha256};
});
const result={verified_at:new Date().toISOString(),artifact_digest:artifactDigest(artifact),expected_artifact_digest:artifact.digest,contract_digest:taskContractDigest(contract),expected_contract_digest:artifact.contract_digest,pins:checks,diffs:diffChecks};
const pass=result.artifact_digest===result.expected_artifact_digest&&result.contract_digest===result.expected_contract_digest&&checks.every(p=>p.sha256===p.expected)&&diffChecks.every(p=>p.reconstructed_admission_sha256===p.expected);
console.log(JSON.stringify({...result,pass},null,2)); if(!pass)process.exitCode=1;
NODE
